import {test} from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {readEventClock,decodeEventBody,encodeEventBody} from "../lib/event-clock.ts";
import {readFrameHeaders} from "../lib/device-frame-headers.ts";

// Generated by actual Swift CloudDeviceClient requests, PairedReceiptPacket,
// and production-mode NumericLogJournal. Synthetic identities, no credentials.
const fixture=JSON.parse(readFileSync(new URL("./fixtures/event-clock-swift.json",import.meta.url),"utf8"));
function noPhoneCoordinate(value:unknown):void {
  if(Array.isArray(value)){value.forEach(noPhoneCoordinate);return;}
  if(!value||typeof value!=="object")return;
  for(const [key,v] of Object.entries(value)){
    if(key==="board_receipt"||key==="receipts")continue;
    assert.ok(!/mono|uptime|_pts/i.test(key),key);noPhoneCoordinate(v);
  }
}
test("T79: decode actual Swift JSON, binary headers, prebuilt paired packet and diagnostic export",()=>{
  noPhoneCoordinate(fixture);
  const clock=readEventClock(fixture.frame.event_clock),frame=decodeEventBody(fixture.frame,clock);
  assert.equal(frame.capture_mono_ms,1000);assert.equal(frame.capture_offset_ms,-13);
  assert.equal(frame.source_seq,1);
  const fromHeaders=readFrameHeaders(new Request("https://fixture.example/v1/device/frame",{headers:fixture.headers}));
  assert.deepEqual(fromHeaders.event_clock,clock);
  const binary=decodeEventBody(fromHeaders,clock);
  assert.equal(binary.capture_mono_ms,frame.capture_mono_ms);assert.equal(binary.capture_offset_ms,frame.capture_offset_ms);
  const paired=decodeEventBody(fixture.paired,readEventClock(fixture.paired.event_clock));
  const click=paired.point_result as {click:{finished_client_mono_ms:number}};
  assert.equal(click.click.finished_client_mono_ms,paired.finished_client_mono_ms);
  assert.deepEqual(encodeEventBody(paired,readEventClock(fixture.paired.event_clock)),fixture.paired);
  assert.equal(fixture.diagnostics.rows[0].schema,"sayso_numeric_log.v2");
  assert.equal(fixture.diagnostics.rows[0].fields.encode_ms,12);
});
